mapper.select:
SELECT 
FROM ams_waiting_list
WHERE store_id = #{storeId}
  AND expected_date = #{date}
  AND status = #{status}
ORDER BY create_time ASC

SELECT w.*, u.nickname as customer_name, u.username as customer_phone, s.name as service_name, t.real_name as tech_name FROM ams_waiting_list w LEFT JOIN sys_user u ON w.customer_id = u.id LEFT JOIN ams_service s ON w.service_id = s.id LEFT JOIN ams_technician_info t ON w.tech_id = t.user_id
w.store_id = #{storeId}
AND (u.nickname LIKE CONCAT('%', #{query.keyword}, '%') OR u.username LIKE CONCAT('%', #{query.keyword}, '%'))
AND w.status = #{query.status}
AND w.expected_date >= #{query.startDate}
AND w.expected_date <= #{query.endDate}
ORDER BY w.create_time DESC
